import { GlProgram } from 'pixi.js';
import Vue, { defineComponent } from 'vue';

import { AssetManager } from '@game-studio/asset-manager';
import { IGameServerResponse, PromoDetails } from '@game-studio/server-comms';

import { BaseGame, buildDynamicString, container, IBroadcastMessage, isInternationalBuild, OrientationValue, OverlaysEventEmitter, queryStringParams, SessionInitialData } from '../..';
import { Bootstrap } from '../../bootstrap';
import { inversifyContainer } from '../../inversify/container';
import { Injects } from '../../inversify/injects';
import { gameConfig } from '../../models/config-model';
import { demoState } from '../../models/demo-model';
import { bootstrapErrorModel } from '../../models/error-model';
import { loggingModel } from '../../models/logging';
import { OperatorModel } from '../../models/operator-model';
import { sessionDataModel } from '../../models/session-data';
import { userModel } from '../../models/user';
import { userPreferences } from '../../models/user-preferences';
import { device } from '../../services/device';
import { environment } from '../../services/environment';
import { eventEmitter } from '../../services/event-emitter';
import { IDisplayConfig, IGameApp, IOverlayStrings } from '../../types';

import { default as DebugOverlay } from '../debug/debug-view.vue';
import { default as ErrorView } from '../error/error.vue';
import { default as GameRules } from '../game-rules/game-rules.vue';
import { default as SessionView } from '../session-manager/session-manager.vue';

interface ISessionDataView extends Vue {
    orientationChange: (orientation: OrientationValue) => void
}

export default defineComponent({
    name: 'GameView',
    components: {
        DebugOverlay,
        ErrorView,
        SessionView
    },
    data() {
        return {
            attemptedLazyLoadResize: false,
            settingsVisible: false,
            htpVisible: false,
            gameRulesVisible: false,
            showSessionData: false,
            sessionDataOpacity: 1,
            userPreferencesState: userPreferences,
            gameRulesComponent: GameRules,
            country: queryStringParams.locale,
            device: device,
            user: userModel,
            overlayStrings: {} as IOverlayStrings,
            showGameNameInVersion: !isInternationalBuild(),
            environment: environment,
            /* eslint-disable @typescript-eslint/no-unused-vars */
            toggleOldHowToPlayBound: (isVisible: boolean) => { return; },
            toggleGameRulesBound: (isVisible: boolean) => { return; },
            enableSessionManager: gameConfig.features.enableSessionManager,
            isSubGame: queryStringParams.isSubGame,
            pixiContextHook: null as { contextChange: (gl: WebGL2RenderingContext) => void } | null
        };
    },
    computed: {
        gameApp() {
            return inversifyContainer.get<IGameApp>(Injects.GameApp);
        },
        theme() {
            return inversifyContainer.get<OperatorModel>(Injects.OperatorModel).theme;
        },
        version() {
            return gameConfig.version;
        },
        sessionStrings() {
            return inversifyContainer.strings.overlays.sessionData;
        },
        isNotProductionEnv() {
            return environment !== 'live';
        },
        sessionDataComponent() {
            return inversifyContainer.sessionDataVue;
        },
        htpComponent() {
            if (device && device.type.isDesktop) {
                return inversifyContainer.desktopHtpVue;
            } else {
                return inversifyContainer.mobileHtpVue;
            }
        },
        bootstrapError() {
            return bootstrapErrorModel.error;
        },
        showBootstrapErrorOverlay() {
            return bootstrapErrorModel.errorState === 'UNHANDLED';
        }
    },
    beforeMount(): void {
        this.toggleOldHowToPlayBound = this.toggleOldHowToPlay.bind(this);
        this.toggleGameRulesBound = this.toggleGameRules.bind(this);
        const overlayText = inversifyContainer.strings.overlays;
        const interactionText = inversifyContainer.strings.interaction;

        overlayText.promo.moreDetails = buildDynamicString(
            overlayText.promo.moreDetails,
            { interactionType: device.type.isDesktop ? interactionText.desktop : interactionText.mobile }
        );

        this.overlayStrings = overlayText;
    },
    async mounted(): Promise<void> {
        this.showSessionData = gameConfig.features.showSessionData;
        const view: ClientRect | DOMRect = (this.$refs.gameView as HTMLCanvasElement).getBoundingClientRect();

        // fix for apple float32 truncating issue in shaders
        // causes sprite animations to wobble
        if (device.info.operatingSystem.is('iOS')) {
            GlProgram.defaultOptions.preferredFragmentPrecision = 'highp';
        }

        function calcResolution(): number {
            if (device.type.realValue === 'desktop') {
                return (window.devicePixelRatio < 2) ? 2 : 4;
            }

            return window.devicePixelRatio;
        }

        const pixiApp = await this.gameApp.initPixi({
            width: view.width,
            height: view.height,
            canvas: this.$refs.gameView as HTMLCanvasElement,
            resolution: calcResolution(),
            sharedTicker: true,
            backgroundAlpha: 0,
            preference: 'webgl',
            resizeTo: this.$refs.gameView as HTMLCanvasElement || undefined
        });

        // prepare logging of which type of render is being used.
        loggingModel.rendererType = pixiApp.renderer.name;

        window.$pixi = pixiApp;

        this.pixiContextHook = {
            contextChange: () => {
                this.gameApp.onWebGLContextRestored?.();
            }
        };
        pixiApp.renderer.runners.contextChange.add(this.pixiContextHook);

        inversifyContainer.cabinet.init()
            .then(() => this.gameApp.preInit())
            .then(() => {
                eventEmitter.on('GLOBAL_DIM_SESSION_DATA', (value: boolean) => {
                    this.sessionDataOpacity = value ? 0.2 : 1;
                });

                inversifyContainer.bigWin.init();
                this.handleFreePlays();
                this.gameApp.init();
                if (bootstrapErrorModel.handledErrorEventCall) {
                    eventEmitter.emit(bootstrapErrorModel.handledErrorEventCall);
                }
                this.prepareLazyAssets();
                this.onOrientationChange();

                if (this.gameApp.postResizeInit) {
                    this.gameApp.postResizeInit();
                }

                if (!bootstrapErrorModel.error && !this.isDemoMode() && gameConfig.features.initialBalanceCheck.shouldCheckBalance && userModel.totalBalance.endBalance <= gameConfig.features.initialBalanceCheck.minBalance && !container.cabinet.inFreePlay) {
                    eventEmitter.emit('GLOBAL_LOW_BALANCE', userModel.totalBalance.endBalance, inversifyContainer.stake.lowestStake);
                }
                // This needs to be called at the end once everything has been initialise/loaded.
                inversifyContainer.frameConnection.operator.onLoaded();

                eventEmitter.on('GLOBAL_ORIENTATION_CHANGE', () => {
                    this.onOrientationChange();
                });
                eventEmitter.on('COMPANION_PANEL_CHANGED', () => {
                    // Capture to size of the canvas as the basis for games to perform resize calculations
                    const view = (this.$refs.gameView as HTMLCanvasElement).getBoundingClientRect();
                    this.gameApp.resize(view.width, view.height);
                });
                eventEmitter.on('GLOBAL_SETTINGS_VISIBILITY_CHANGE', this.onToggleSettingsVisibility, this);
                eventEmitter.on('POPUP_TOGGLE_OLD_HTP', this.toggleOldHowToPlayBound);
                eventEmitter.on('POPUP_TOGGLE_GAME_RULES', this.toggleGameRulesBound);
                eventEmitter.on('POPUP_TOGGLE_HTP_POPUP', () => {
                    this.settingsVisible = false;
                    this.gameRulesVisible = false;
                });

                if (inversifyContainer.gameModel.isNewPlayer) {
                    eventEmitter.emit('POPUP_TOGGLE_HTP_NUDGE_POPUP', true);
                }

                return;
            }).then(() => {
                this.$emit('loadComplete');
                loggingModel.recordLoadEndTime();
                loggingModel.logBeginSession();
            });
    },
    beforeUnmount(): void {
        const renderer = window.$pixi.renderer;
        if (renderer?.runners?.contextChange && this.pixiContextHook) {
            renderer.runners.contextChange.remove(this.pixiContextHook);
        }

        this.pixiContextHook = null;
    },
    methods: {
        setOverlayState(value: boolean): void {
            device.showSessionInfoOverGame = value;
        },
        handleFreePlays(): void {
            if (gameConfig.supportsFreeplays && userModel.freePlayBalance > 0) {
                if (queryStringParams.locale === 'it-it') {
                    inversifyContainer.cabinet.disablePurchaseButton();
                    eventEmitter.emit('GLOBAL_FREEPLAY_SESSION_START_ITALY');
                }

                eventEmitter.emit('GLOBAL_FREE_PLAY_EARNED', userModel.freePlayBalance);
            }
        },
        /** Ensures any lazy assets are loaded before their related components are initialised */
        prepareLazyAssets(): void {
            const usingLocalAssets = gameConfig.features.usingLocalAssets;
            const usingLazyAssets = container.skin.lazyAssetList !== undefined;
            const isLazyAssetMissingFromLoader = AssetManager.hasAsset('lazy-asset-list') === false;

            if ((usingLocalAssets && !usingLazyAssets) || (!usingLocalAssets && isLazyAssetMissingFromLoader)) {
                BaseGame.isLazyLoadComplete = true;
                return;
            }

            if (!BaseGame.isLazyLoadComplete) {
                Bootstrap.loadLazyAssets()
                    .then((resources) => {
                        if (Object.keys(resources).length > 0) {
                            this.onLazyLoadComplete();
                        }

                        BaseGame.isLazyLoadComplete = true;
                        eventEmitter.emit('GLOBAL_LAZY_LOAD_COMPLETE');
                        return;
                    });
            } else {
                this.onLazyLoadComplete();
            }
        },
        /** Initialises the games lazy components, displaying a warning if the game doesn't define initLazyComponents */
        onLazyLoadComplete(): void {
            if (this.gameApp.initLazyComponents) {
                this.gameApp.initLazyComponents().then(() => {
                    BaseGame.isLazyInitComplete = true;

                    eventEmitter.emit('GLOBAL_LAZY_INIT_COMPLETE');
                    return;
                });
            } else {
                console.warn('Warning: Lazy asset list detected with no initLazyComponents definition. Are you missing a definition for initLazyComponents inside the IGameApp implementation?');
            }
        },
        resizeLazyComponentsAfterLoad(width: number, height: number): void {
            if (this.gameApp.resizeLazyComponents) {
                this.gameApp.resizeLazyComponents(width, height);
            } else {
                console.warn('Warning: Initialise lazy assets detected with no resizeLazyComponents definition. Are you missing a definition for resizeLazyComponents inside the IGameApp implementation?');
            }
        },
        onOrientationChange(): void {
            Vue.nextTick(() => {
                if (device.type.isDesktop) {
                    device.viewport.setDesktopDimensions({
                        width: window.innerWidth,
                        height: window.innerHeight
                    });
                }

                device.sessionClientHeight = (this.$refs.sessionData as Vue)?.$el?.clientHeight ?? 0;

                // Capture to size of the canvas as the basis for games to perform resize calculations
                const view = (this.$refs.gameView as HTMLCanvasElement).getBoundingClientRect();
                this.gameApp.resize(view.width, view.height);

                if (this.$refs.sessionData) {
                    (this.$refs.sessionData as ISessionDataView).orientationChange(device.orientation.value);
                }

                const usingLocalAssets = gameConfig.features.usingLocalAssets;
                const usingLazyAssets = container.skin.lazyAssetList !== undefined;
                const isLazyAssetMissingFromLoader = AssetManager.hasAsset('lazy-asset-list') === false;

                if ((usingLocalAssets && !usingLazyAssets) || (!usingLocalAssets && isLazyAssetMissingFromLoader)) {
                    return;
                }

                if (!BaseGame.isLazyInitComplete) {
                    if (!this.attemptedLazyLoadResize) {
                        this.attemptedLazyLoadResize = true;

                        eventEmitter.once('GLOBAL_LAZY_INIT_COMPLETE', () => {
                            this.resizeLazyComponentsAfterLoad(view.width, view.height);
                        });
                    }
                } else {
                    this.resizeLazyComponentsAfterLoad(view.width, view.height);
                }
            });
        },
        onServerSuccess(callback: (response: unknown) => void, context: Vue): void {
            inversifyContainer.gameServer.on('ON_SUCCESSFUL_RESULT', callback, context);
            eventEmitter.on('GLOBAL_SESSION_CREATED', callback);
        },
        onGameComplete(callback: () => void, context: Vue): void {
            eventEmitter.on('GAME_COMPLETE', callback, context);
        },
        onJackpotWin(callback: (prize: number) => void, context: Vue): void {
            eventEmitter.on('GAME_JACKPOT_WIN', callback, context);
        },
        toggleOldHowToPlay(isVisible: boolean): void {
            this.htpVisible = isVisible;
        },
        toggleGameRules(isVisible: boolean): void {
            // Only needed in the app as the game rules is handled by the settings package outside of the app
            if (!device.type.isApp) {
                return;
            }

            this.gameRulesVisible = isVisible;
        },
        onToggleSettingsVisibility(isVisible: boolean): void {
            this.settingsVisible = isVisible;
            this.htpVisible = this.gameRulesVisible = false;
        },
        currencyFormatter(subunits: number): string {
            return inversifyContainer.currencyFormatter.precise(subunits);
        },
        getFriendlyName(): string {
            const displayName = inversifyContainer.strings.displayName;
            const skin = queryStringParams.currentSkin;
            return typeof displayName === 'string' ? displayName : displayName[skin];
        },
        isDemoMode(): boolean {
            return demoState.isDemoMode;
        },
        onOutOfPlays(callback: () => void, context: Vue): void {
            eventEmitter.on('GAME_DEMO_OUT_OF_PLAYS', callback, context);
        },
        getDisplayConfig(): IDisplayConfig | undefined {
            return inversifyContainer.displayConfig;
        },
        getInitialSessionInfo(): SessionInitialData {
            return {
                balance: demoState.isDemoMode ? demoState.demoGamesRemaining : userModel.totalBalance.startBalance,
                isUnAuthDemo: demoState.isUnauthenticatedDemo,
                gameId: inversifyContainer.gameModel.gameId,
                totalSpend: sessionDataModel.status.CurrentBet,
                sessionData: {
                    totalWin: sessionDataModel.status.TotalWinnings,
                    sessionBalance: sessionDataModel.status.NetBalance!
                }
            };
        },
        onTopPrizeMessage(callback: (data: IBroadcastMessage) => void, context: Vue): void {
            OverlaysEventEmitter.on('showTopPrize', (data) => {
                const isUkBingoSite = queryStringParams.locale === 'en-gb' && queryStringParams.launchedFrom === 'bingo';
                if (this.isSubGame === false && userPreferences.notifications && !isUkBingoSite) {
                    callback.call(context, data);
                }
            });
        },
        onPromoMessage(callback: (promoDetails: PromoDetails) => void, context: Vue): void {
            if (queryStringParams.isSubGame === false) {
                eventEmitter.on('GLOBAL_PROMO', callback, context);
            }
        },
        goToPromo(webEndpoint: string): void {
            inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'navigation', data: { type: 'url', location: webEndpoint } });
        },
        onGoToPromoTandCs(): void {
            inversifyContainer.frameConnection.operator.onUserActionRequired({ type: 'navigation', data: { type: 'location', location: 'promotions_terms-and-conditions' } });
        },
        onFreePlayMessage(callback: (data: number) => void, context: Vue): void {
            eventEmitter.on('GLOBAL_FREE_PLAY_EARNED', callback, context);
        },
        onFreePlayEnded(callback: (payout: number, message: string) => void, context: Vue): void {
            eventEmitter.on('GLOBAL_FREE_PLAY_ENDED', callback, context);
        },
        onCloseEndFreePlay(): void {
            inversifyContainer.cabinet.leaveFreePlay();

            if (queryStringParams.locale === 'it-it') {
                eventEmitter.emit('POPUP_SHOW_WALLET', {} as IGameServerResponse);
            }
        },
        onSettingsVisibilityChange(callback: (data?: boolean) => void, context: Vue): void {
            eventEmitter.on('GLOBAL_SETTINGS_VISIBILITY_CHANGE', callback, context);
        },
        // TODO: confirm this can be removed
        returnToLobby(): void {
            // TODO: There is no lobby to return too, what do?
            //     inversifyContainer.frameConnection.onExitGame();
            //     inversifyContainer.frameConnection.onEnterLobby(gameConfig.gameCategory);
        },
        getLabelJustification() {
            return gameConfig.features.sessionDataJustification;
        },
        freePlayIconUrl(): string {
            switch (this.country) {
                case 'it-it':
                    return './static/assets/core/cabinet/textures/it/free-play-icon.png';
                case 'es-es':
                    return './static/assets/core/cabinet/textures/es/free-play-icon.png';
                default:
                    return './static/assets/core/cabinet/textures/base/free-play-icon.png';
            }
        },
    }
});